mapper.select:
SELECT t.id, t.colony_version AS colonyVersion, t.wgt_version AS wgtVersion, t.upgrade_url AS upgradeUrl, t.upgrade_describe AS upgradeDescribe, t.is_force_upgrade isForceUpgrade, t.wgt_package_name AS wgtPackageName, t.type as type FROM bs_wgt_upgrade_info t where t.delete_flag = '0'
AND t.colony_version like CONCAT('%', #{param.colonyVersion}, '%')
AND t.id =#{param.id}

mapper.update:
UPDATE bs_wgt_upgrade_info
is_force_upgrade = #{param.isForceUpgrade}, wgt_package_name = #{param.wgtPackageName}, upgrade_url = #{param.upgradeUrl}, wgt_version = #{param.wgtVersion}, upgrade_describe = #{param.upgradeDescribe}, platform_code = #{param.platformCode}, modifier = #{param.modifier}, update_time = #{param.updateTime},
WHERE id = #{param.id}

UPDATE bs_mini_program_upgrade_info
mini_program_version = #{param.miniProgramVersion}, code_version = #{param.codeVersion}, modifier = #{param.modifier}, update_time = now()
WHERE id = #{param.id}
